type Base = { title: string; archived: boolean; id?: string; revision?: number; updatedAt?: string; createdAt?: string };
type Summary = Base & { category?: string; tags?: string[]; color?: string; size?: string; status?: string; stage?: string; date?: string; calories?: number; protein?: number; fiber?: number; carbs?: number | null; fat?: number | null; minutes?: number; source?: string; proteinTarget?: number | null; fiberTarget?: number | null; baselineCalories?: number | null };
type Listing = { items: Summary[]; total: number; nextOffset: number | null };
export type PersonalDraftCache = Record<string, { value: unknown; dirty: boolean }>;
type Props = { drafts: PersonalDraftCache };
const PATH = '/api/platform/personal';
const categories = ['Science', 'Biology', 'Tech', 'Bio tech', 'Bio chem', 'Nuclear physics', 'Nano technology', 'AI'];
const platforms = ['YouTube', 'SoundCloud', 'Spotify', 'Apple Music'];
const today = () => { const d = new Date(); return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`; };

function useRecords<T extends Base>(collection: string, drafts: PersonalDraftCache, day = '') {
  const [value, setValue] = useState<T | null>((drafts[collection]?.value as T | null) ?? null);
  const [dirty, setDirty] = useState(drafts[collection]?.dirty ?? false);
  const [listing, setListing] = useState<Listing>({ items: [], total: 0, nextOffset: null });
  const [archived, setArchived] = useState(false); const [offset, setOffset] = useState(0);
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [message, setMessage] = useState('');
  const locked = useRef(false); const ticket = useRef(0);
  function remember(next: T | null, changed: boolean) { setValue(next); setDirty(changed); drafts[collection] = { value: next, dirty: changed }; }
  async function load() {
    if (!LIVE_API) return;
    const current = ++ticket.current;
    const result = await api<Listing>('GET', `${PATH}/${collection}?day=${day}&archived=${archived}&offset=${offset}`);
    if (current === ticket.current) setListing(result);
  }
  useEffect(() => { void load().catch(e => setError(errorText(e))); return () => { ticket.current++; }; }, [collection, day, archived, offset]);
  // ZAE saved something into this tab from the chat: show it without a manual refresh.
  useEffect(() => {
    const changed = () => { void load().catch(e => setError(errorText(e))); };
    window.addEventListener('zae:records-changed', changed);
    return () => window.removeEventListener('zae:records-changed', changed);
  }, [collection, day, archived, offset]); // eslint-disable-line react-hooks/exhaustive-deps
  async function perform(action: () => Promise<void>) {
    if (locked.current) return;
    locked.current = true; setBusy(true); setError(''); setMessage('');
    try { await action(); await load(); } catch (e) { setError(errorText(e)); }
    finally { locked.current = false; setBusy(false); }
  }
  function edit(changes: Partial<T>) { if (value) remember({ ...value, ...changes }, true); }
  function create(next: T) { if (!dirty) { remember(next, true); setMessage(''); } }
  function open(id: string) { if (!dirty) void perform(async () => remember(await api<T>('GET', `${PATH}/${collection}/${id}`), false)); }
  async function save(changes: Partial<T> = {}) {
    if (!value) return;
    const { id, revision, updatedAt: _updated, createdAt: _created, ...record } = { ...value, ...changes };
    const saved = await api<T>(id ? 'PUT' : 'POST', `${PATH}/${collection}${id ? `/${id}` : ''}`, { record, ...(id ? { revision } : {}) });
    remember(saved, false); setMessage('Saved on your PC.');
  }
  const disabled = !LIVE_API || busy;
  const notice = <>{!LIVE_API && <p>Connect to ZAE to load and save your records.</p>}{error && <p role="alert" className="platform-error">{error}</p>}{message && <p role="status">{message}</p>}</>;
  const controls = <div className="platform-inline personal-controls"><label className="platform-check"><input type="checkbox" checked={archived} disabled={disabled} onChange={e => { setArchived(e.target.checked); setOffset(0); }}/>Archived</label><button disabled={disabled} onClick={() => void perform(async () => {})}>Refresh</button><small>{listing.total} records</small>{offset > 0 && <button disabled={disabled} onClick={() => setOffset(Math.max(0, offset - 100))}>Previous</button>}{listing.nextOffset != null && <button disabled={disabled} onClick={() => setOffset(listing.nextOffset!)}>More</button>}</div>;
  const actions = <div className="platform-inline personal-actions"><button disabled={disabled || !value?.title.trim() || !dirty} onClick={() => void perform(() => save())}>Save</button><button disabled={disabled || !value} onClick={() => { remember(null, false); setMessage('Editor closed. Unsaved changes discarded.'); }}>Close / discard</button>{value?.id && <button disabled={disabled || dirty} onClick={() => void perform(() => save({ archived: !value.archived } as Partial<T>))}>{value.archived ? 'Restore' : 'Archive'}</button>}<small>{dirty ? 'Unsaved · draft stays while switching tabs' : 'Saved'}</small></div>;
  return { value, dirty, listing, disabled, busy, notice, controls, actions, create, edit, open, perform, setMessage, save };
}

type Stroke = { color: '#f2b95f' | '#75cfff' | '#a5eeaa' | '#f49cb8' | '#eeeeee'; width: number; points: number[][] };
type Project = Base & { category: string; tags?: string[]; noteIds?: string[]; color: string; size: string; status: string; body: string; blueprint: string; scenarios: string; unit: string; boardWidth: number; strokes: Stroke[]; referenceImage: string };
const emptyProject = (): Project => ({ title: '', archived: false, category: 'Tech', tags: [], color: 'amber', size: 'medium', status: 'Idea', body: '', blueprint: '', scenarios: '', unit: 'mm', boardWidth: 100, strokes: [], referenceImage: '' });

function Sketch({ value, onChange, disabled }: { value: Project; onChange: (strokes: Stroke[]) => void; disabled: boolean }) {
  const svg = useRef<SVGSVGElement>(null); const active = useRef<Stroke | null>(null); const pointer = useRef<number | null>(null);
  const [preview, setPreview] = useState<Stroke | null>(null); const [color, setColor] = useState<Stroke['color']>('#f2b95f'); const [line, setLine] = useState(false);
  function point(e: PointerEvent<SVGSVGElement>) { const rect = e.currentTarget.getBoundingClientRect(); return [Math.round(Math.max(0, Math.min(1000, (e.clientX - rect.left) / rect.width * 1000))), Math.round(Math.max(0, Math.min(600, (e.clientY - rect.top) / rect.height * 600)))]; }
  const count = value.strokes.reduce((sum, stroke) => sum + stroke.points.length, 0);
  function end(e: PointerEvent<SVGSVGElement>, cancel = false) {
    if (pointer.current !== e.pointerId) return;
    const stroke = active.current; active.current = null; pointer.current = null; setPreview(null);
    if (stroke && !cancel) onChange([...value.strokes, stroke]);
  }
  function exportDrawing() {
    if (!svg.current) return;
    const clone = svg.current.cloneNode(true) as SVGSVGElement;
    const millimeters: Record<string, number> = { mm: 1, cm: 10, m: 1000, in: 25.4, ft: 304.8 };
    clone.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
    clone.setAttribute('width', `${value.boardWidth * millimeters[value.unit]}mm`); clone.setAttribute('height', `${value.boardWidth * .6 * millimeters[value.unit]}mm`);
    const url = URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(clone)], { type: 'image/svg+xml' }));
    const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${value.title.replace(/[^a-z0-9-]/gi, '_') || 'sketch'}.svg`; anchor.click(); window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  }
  const last = preview ?? value.strokes[value.strokes.length - 1];
  const length = last ? last.points.slice(1).reduce((sum, p, i) => sum + Math.hypot(p[0] - last.points[i][0], p[1] - last.points[i][1]) * value.boardWidth / 1000, 0) : 0;
  const shown = [...value.strokes, ...(preview ? [preview] : [])];
  return <div className="personal-sketch">
    <div className="platform-inline"><label>Ink<select value={color} disabled={disabled} onChange={e => setColor(e.target.value as Stroke['color'])}><option value="#f2b95f">Amber</option><option value="#75cfff">Blue</option><option value="#a5eeaa">Green</option><option value="#f49cb8">Rose</option><option value="#eeeeee">White</option></select></label><label className="platform-check"><input type="checkbox" checked={line} onChange={e => setLine(e.target.checked)}/>Straight line</label><button type="button" disabled={disabled || !value.strokes.length} onClick={() => onChange(value.strokes.slice(0, -1))}>Undo stroke</button><button type="button" disabled={!value.strokes.length} onClick={exportDrawing}>Export SVG</button></div>
    <svg ref={svg} viewBox="0 0 1000 600" role="img" aria-label="Project sketch. Draw with a mouse, finger or stylus. Grid spacing is one tenth of the board width."
      onPointerDown={e => { if (disabled || value.strokes.length >= 300 || count >= 20000 || pointer.current !== null || e.button !== 0) return; e.currentTarget.setPointerCapture(e.pointerId); pointer.current = e.pointerId; active.current = { color, width: 2, points: [point(e)] }; setPreview(active.current); }}
      onPointerMove={e => { if (!active.current || pointer.current !== e.pointerId) return; const points = active.current.points; if (!line && (points.length >= 5000 || points.length + count >= 20000)) return; active.current = { ...active.current, points: line ? [points[0], point(e)] : [...points, point(e)] }; setPreview(active.current); }}
      onPointerUp={e => end(e)} onPointerCancel={e => end(e, true)}>
      <rect width="1000" height="600" fill="#101b24"/>{Array.from({ length: 11 }, (_, i) => <line key={`v${i}`} x1={i * 100} x2={i * 100} y1="0" y2="600" stroke="#34505c" strokeWidth="1"/>)}{Array.from({ length: 7 }, (_, i) => <line key={`h${i}`} x1="0" x2="1000" y1={i * 100} y2={i * 100} stroke="#34505c" strokeWidth="1"/>)}
      {shown.map((stroke, i) => <polyline key={i} points={stroke.points.map(p => p.join(',')).join(' ')} fill="none" stroke={stroke.color} strokeWidth={stroke.width} strokeLinecap="round" strokeLinejoin="round"/>)}
    </svg><small>Board: {value.boardWidth} × {+(value.boardWidth * .6).toFixed(4)} {value.unit}. Last stroke: {length.toFixed(2)} {value.unit}. Concept measurements; confirm tolerances in CAD.</small>
  </div>;
}

export function WorkbenchPanel({ drafts }: Props) {
  const r = useRecords<Project>('workbench', drafts); const [category, setCategory] = useState('All'); const [query, setQuery] = useState(''); const p = r.value;
  return <section className="platform-panel personal-panel" aria-label="Workbench" aria-busy={r.busy}>
    <div className="platform-panel__heading"><div><span className="subheading">IDEAS INTO PROJECTS</span><h2>Workbench</h2></div><button disabled={r.disabled || r.dirty} onClick={() => r.create(emptyProject())}>New project</button></div>{r.notice}
    <div className="personal-tabs" aria-label="Project subjects">{['All', ...categories].map(name => <button key={name} aria-pressed={category === name} onClick={() => setCategory(name)}>{name}</button>)}</div>
    <label>Find project<input type="search" value={query} onChange={e => setQuery(e.target.value)} placeholder="Project title…"/></label>{r.controls}
    <div className="personal-forum">{r.listing.items.filter(item => (category === 'All' || item.category === category || (item.tags ?? []).includes(category)) && item.title.toLowerCase().includes(query.toLowerCase())).map(item => <button key={item.id} disabled={r.disabled || r.dirty} className={`personal-project personal-project--${item.size} personal-project--${item.color}`} aria-pressed={item.id === p?.id} onClick={() => r.open(item.id!)}><small>{[item.category, ...(item.tags ?? []).filter(tag => tag !== item.category)].join(' · ')} · {item.status}</small><strong>{item.title}</strong><span>Updated {new Date(item.updatedAt!).toLocaleDateString()}</span></button>)}</div>
    {!r.listing.total && <p>Start a project to keep its notes, sketches, blueprint references and experiments together.</p>}
    {p && <div className="personal-editor"><h3>{p.id ? 'Project details' : 'New project'}</h3><fieldset disabled={r.disabled}>
      <label>Project title<input required maxLength={160} value={p.title} onChange={e => r.edit({ title: e.target.value })}/></label>
      <div className="personal-fields"><Select label="Subject" value={p.category} options={categories} change={category => r.edit({ category })}/><Select label="Stage" value={p.status} options={['Idea', 'Research', 'Prototype', 'Testing', 'Complete']} change={status => r.edit({ status })}/><Select label="Card color" value={p.color} options={['amber', 'blue', 'green', 'rose', 'violet']} change={color => r.edit({ color })}/><Select label="Card size" value={p.size} options={['small', 'medium', 'large']} change={size => r.edit({ size })}/></div>
      <fieldset className="personal-crosstags"><legend>Also tag as</legend>
        {categories.filter(name => name !== p.category).map(name => { const on = (p.tags ?? []).includes(name);
          return <button type="button" key={name} aria-pressed={on} className={on ? 'personal-crosstag personal-crosstag--on' : 'personal-crosstag'}
            onClick={() => r.edit({ tags: on ? (p.tags ?? []).filter(tag => tag !== name) : [...(p.tags ?? []), name] })}>{on ? '✓ ' : '+ '}{name}</button>; })}
        <small>The project shows under every subject it's tagged with.</small>
      </fieldset>
      <label>Project description<textarea rows={5} maxLength={30000} value={p.body} onChange={e => r.edit({ body: e.target.value })}/></label>
      <ProjectNotes projectTitle={p.title} noteIds={p.noteIds ?? []} onLink={ids => p.id && !r.dirty ? r.perform(() => r.save({ noteIds: ids })) : r.edit({ noteIds: ids })}/>
      <label>Blueprint file or link<input maxLength={2000} value={p.blueprint} onChange={e => r.edit({ blueprint: e.target.value })} placeholder="Reference to your CAD file, drawing or shared export"/></label>
      <label>Import sketch / blueprint image<input type="file" accept="image/png,image/jpeg" onChange={event => { const file=event.target.files?.[0]; event.target.value=''; if (!file) return; void r.perform(async () => { if(file.size>600000) throw new Error('Export a PNG or JPEG reference under 600 KB.'); const image=await new Promise<string>((resolve,reject) => { const reader=new FileReader(); reader.onload=()=>resolve(String(reader.result)); reader.onerror=()=>reject(new Error('Image could not be read.')); reader.readAsDataURL(file); }); r.edit({ referenceImage:image }); }); }}/></label>
      {p.referenceImage && <figure className="personal-reference"><img src={p.referenceImage} alt={`Sketch or blueprint reference for ${p.title}`}/><figcaption>Imported reference · kept on your PC</figcaption><button type="button" onClick={() => r.edit({ referenceImage:'' })}>Remove image from draft</button></figure>}
      <div className="personal-fields"><NumberField label="Sketch board width" value={p.boardWidth} min={.001} change={boardWidth => r.edit({ boardWidth })}/><Select label="Units" value={p.unit} options={['mm', 'cm', 'm', 'in', 'ft']} change={unit => r.edit({ unit })}/></div>
      <Sketch key={p.id ?? 'new'} value={p} disabled={r.disabled} onChange={strokes => r.edit({ strokes })}/>
      <label>Hypotheses, test conditions and results<textarea rows={5} maxLength={10000} value={p.scenarios} onChange={e => r.edit({ scenarios: e.target.value })} placeholder="Record the question, dimensions, materials, loads, assumptions and actual CAD / simulation results."/></label>
      <small>Scenario notes do not run a physics solver. Use the tools below for engineering analysis.</small>
    </fieldset>{r.actions}</div>}
    <details className="personal-resources"><summary>Sketching and blueprint tools · checked October 24, 2026</summary><p><a href="https://www.adobe.com/products/fresco.html" target="_blank" rel="noreferrer">Adobe Fresco</a> — free drawing on iPad and supported Windows devices. <a href="https://www.concepts.app/en/pricing-explained/" target="_blank" rel="noreferrer">Concepts</a> — free basics; optional one-time Essentials per platform. <a href="https://www.sketchbook.com/" target="_blank" rel="noreferrer">Sketchbook</a> — iPad basics free; Windows Pro is a separate one-time purchase.</p><p><a href="https://www.freecad.org/features.php" target="_blank" rel="noreferrer">FreeCAD</a> — free Windows CAD with real units, dimensioned drawings and FEM analysis; no native iPad app. <a href="https://support.shapr3d.com/hc/en-us/articles/7872024839452-Shapr3D-Basic" target="_blank" rel="noreferrer">Shapr3D Basic</a> — free iPad/Windows CAD, two projects and limited export; advanced drawings are paid. <a href="https://www.onshape.com/en/pricing" target="_blank" rel="noreferrer">Onshape Free</a> — iPad/browser CAD for noncommercial, public projects. Keep private inventions in a private tool.</p></details>
  </section>;
}

type Release = { platform: string; url: string };
type Stat = { platform: string; date: string; metric: string; value: number; source: string; method: 'manual' };
type Music = Base & { stage: string; projectFile: string; bpm: number | null; key: string; body: string; releases: Release[]; stats: Stat[] };
const emptyMusic = (): Music => ({ title: '', archived: false, stage: 'Idea', projectFile: '', bpm: null, key: '', body: '', releases: [], stats: [] });

export function MusicPanel({ drafts }: Props) {
  const r = useRecords<Music>('music', drafts); const m = r.value;
  const [release, setRelease] = useState<Release>({ platform: 'YouTube', url: '' });
  const [stat, setStat] = useState<Stat>({ platform: 'YouTube', date: today(), metric: 'Views', value: 0, source: '', method: 'manual' });
  return <section className="platform-panel personal-panel" aria-label="Music projects" aria-busy={r.busy}>
    <div className="platform-panel__heading"><div><span className="subheading">WRITE · RECORD · RELEASE</span><h2>Music</h2></div><button disabled={r.disabled || r.dirty} onClick={() => r.create(emptyMusic())}>New song</button></div>{r.notice}{r.controls}
    <div className="personal-forum">{r.listing.items.map(item => <button className="personal-project" disabled={r.disabled || r.dirty} key={item.id} onClick={() => r.open(item.id!)}><small>{item.stage}</small><strong>{item.title}</strong></button>)}</div>
    {!r.listing.total && <p>Track your GarageBand sessions, release links and each song's progress here.</p>}
    {m && <div className="personal-editor"><fieldset disabled={r.disabled}><label>Song title<input maxLength={160} value={m.title} onChange={e => r.edit({ title: e.target.value })}/></label><div className="personal-fields"><Select label="Production stage" value={m.stage} options={['Idea', 'Writing', 'Recording', 'Mixing', 'Mastering', 'Released']} change={stage => r.edit({ stage })}/><NumberField label="BPM (optional)" value={m.bpm} optional change={bpm => r.edit({ bpm })}/><label>Key<input maxLength={40} value={m.key} onChange={e => r.edit({ key: e.target.value })}/></label></div>
      <label>GarageBand project reference<input maxLength={2000} value={m.projectFile} onChange={e => r.edit({ projectFile: e.target.value })} placeholder="File location or iCloud reference; reference only"/></label><label>Session notes<textarea rows={5} maxLength={30000} value={m.body} onChange={e => r.edit({ body: e.target.value })}/></label>
      <h3>Releases</h3>{m.releases.map((item, i) => <div className="platform-inline" key={i}><span>{item.platform}</span><a href={item.url} target="_blank" rel="noreferrer">Open release</a><button onClick={() => r.edit({ releases: m.releases.filter((_, index) => index !== i) })}>Remove link</button></div>)}
      <div className="personal-fields"><Select label="Release platform" value={release.platform} options={platforms} change={platform => setRelease({ ...release, platform })}/><label>Release URL<input type="url" maxLength={2000} value={release.url} onChange={e => setRelease({ ...release, url: e.target.value })}/></label><button disabled={!release.url.startsWith('https://') || m.releases.length >= 12} onClick={() => { r.edit({ releases: [...m.releases, release] }); setRelease({ ...release, url: '' }); }}>Add release</button></div>
      <h3>Song statistics</h3><p>Manual observations from YouTube, SoundCloud, Spotify and Apple Music. Automatic connections are not configured yet. Compare the same platform and metric; plays, views and listeners are different measures.</p>
      <div className="personal-fields"><Select label="Statistics platform" value={stat.platform} options={platforms} change={platform => setStat({ ...stat, platform })}/><Select label="Metric" value={stat.metric} options={['Views', 'Plays', 'Listeners', 'Likes', 'Saves']} change={metric => setStat({ ...stat, metric })}/><label>Observed date<input type="date" value={stat.date} onChange={e => setStat({ ...stat, date: e.target.value })}/></label><NumberField label="Observed count" value={stat.value} change={value => setStat({ ...stat, value })}/><label>Source / reporting period<input maxLength={500} placeholder="e.g. Artist dashboard, lifetime count" value={stat.source} onChange={e => setStat({ ...stat, source: e.target.value })}/></label></div>
      <button disabled={!stat.date || !stat.source.trim() || m.stats.length >= 300} onClick={() => r.edit({ stats: [...m.stats, { ...stat, value: Math.trunc(stat.value) }] })}>Add dated statistic</button>
      <div className="personal-table-wrap"><table><thead><tr><th>Date</th><th>Platform</th><th>Metric</th><th>Count</th><th>Source / period</th><th></th></tr></thead><tbody>{m.stats.map((item, i) => <tr key={i}><td>{item.date}</td><td>{item.platform}</td><td>{item.metric}</td><td>{item.value.toLocaleString()}</td><td>{item.source} · manual</td><td><button onClick={() => r.edit({ stats: m.stats.filter((_, index) => index !== i) })}>Remove</button></td></tr>)}</tbody></table></div>
    </fieldset>{r.actions}</div>}
  </section>;
}

type Food = Base & { date: string; calories: number; protein: number; fiber: number; carbs?: number; fat?: number; saturatedFat?: number; sugars?: number; sodiumMg?: number; cholesterolMg?: number; source: string; items?: any[]; sourceDetails?: any[] };
type Recipe = Base & { category: string; servings: number; ingredients: any[]; instructions: string; source: string };
type Exercise = Base & { date: string; minutes: number; calories: number; source: string; notes: string };
type Step = { exercise: string; prescription: string; done: boolean; sets?: number | null; reps?: string; duration?: string; restSeconds?: number | null; equipment?: string; notes?: string };
type Plan = Base & { sourceUrl: string; sourceText: string; sourceName: string; schedule: string; steps: Step[]; sessions: { date: string; steps: Step[] }[] };
type Settings = Base & { proteinTarget: number | null; fiberTarget: number | null; baselineCalories: number | null };
type TrainingSource = { sourceUrl: string; sourceText: string; sourceName: string; steps: Step[]; note: string };

export function FitnessPanel({ drafts, embedded = false, page: shown }: Props & { embedded?: boolean; page?: string }) {
  // Inside Fitness & Health each of these pages is its own tab, so the tab picks the page (shown) and this panel hides its own row.
  const [day, setDay] = useState(today()); const [ownPage, setPage] = useState(embedded ? 'Log' : 'Training program'); const page = shown ?? ownPage;
  const [mealText, setMealText] = useState(''); const [mealPreview, setMealPreview] = useState<any>(null); const [mealBusy, setMealBusy] = useState(false); const [mealError, setMealError] = useState('');
  const [barcode, setBarcode] = useState(''); const [scanResult, setScanResult] = useState<any>(null); const [scanBusy, setScanBusy] = useState(false); const [scanning, setScanning] = useState(false);
  const [askSetup, setAskSetup] = useState(0);
  useEffect(() => { if (embedded) return; const open = () => { setPage('Training program'); setAskSetup(n => n + 1); }; window.addEventListener('zae:training-setup', open); return () => window.removeEventListener('zae:training-setup', open); }, [embedded]);
  const food = useRecords<Food>('food', drafts, day); const exercise = useRecords<Exercise>('exercise', drafts, day); const plans = useRecords<Plan>('plans', drafts); const recipes = useRecords<Recipe>('recipes', drafts); const settings = useRecords<Settings>('fitness-settings', drafts);
  const [totals, setTotals] = useState<{ calories: number; protein: number; fiber: number; carbs: number | null; fat: number | null; saturatedFat: number | null; sugars: number | null; sodiumMg: number | null; cholesterolMg: number | null; burned: number; baseline: number | null; proteinTarget: number | null; fiberTarget: number | null } | null>(null);
  const [sourceText, setSourceText] = useState(''); const [sourceUrl, setSourceUrl] = useState('');
  const f = food.value; const e = exercise.value; const p = plans.value; const s = settings.value;
  const dirty = food.dirty || exercise.dirty || plans.dirty || settings.dirty;
  useEffect(() => { const open = (event: Event) => { const detail = (event as CustomEvent<{ description?: string }>).detail; if (!detail?.description) return; setPage('Log'); setMealText(detail.description); setMealPreview(null); setMealError(''); }; window.addEventListener('zae:food-meal', open); return () => window.removeEventListener('zae:food-meal', open); }, []);
  useEffect(() => { const open = () => { setPage('Scan food'); setScanResult(null); setMealError(''); setScanning(true); }; window.addEventListener('zae:food-scan', open); return () => window.removeEventListener('zae:food-scan', open); }, []);
  async function previewMeal(description = mealText) {
    if (!description.trim()) return; setMealBusy(true); setMealError('');
    try { setMealPreview(await api<any>('POST', `${PATH}/nutrition/meal-preview`, { description })); }
    catch (error) { setMealError(errorText(error)); } finally { setMealBusy(false); }
  }
  async function scanBarcode(code = barcode) {
    if (!code.trim()) return; setScanBusy(true); setScanResult(null); setMealError('');
    try { setScanResult(await api<any>('POST', `${PATH}/nutrition/barcode`, { barcode: code })); }
    catch (error) { setMealError(errorText(error)); } finally { setScanBusy(false); }
  }
  async function scanBarcodePhoto(file?: File) {
    if (!file) return; setScanBusy(true); setMealError('');
    try { const value = await readPhoto(file); if (!value) throw new Error('No barcode found in that photo. Try a sharper picture, straight on and filling the frame, or type the digits.'); setBarcode(value); await scanBarcode(value); } catch (error) { setMealError(errorText(error)); setScanBusy(false); }
  }
  async function scanLabel(file?: File) {
    if (!file) return; setScanBusy(true); setScanResult(null); setMealError('');
    try { if (file.size > 8_000_000) throw new Error('Choose a photo under 8 MB.'); const data = new Uint8Array(await file.arrayBuffer()); let binary = ''; data.forEach(byte => { binary += String.fromCharCode(byte); }); setScanResult(await api<any>('POST', `${PATH}/nutrition/label`, { data: btoa(binary) }, { timeoutMs: 120000 })); }
    catch (error) { setMealError(errorText(error)); } finally { setScanBusy(false); }
  }
  useEffect(() => { let active = true; if (LIVE_API) void api<typeof totals>('GET', `${PATH}/fitness-summary?day=${day}`).then(value => { if (active) setTotals(value); }).catch(() => { if (active) setTotals(null); }); return () => { active = false; }; }, [day, food.listing, exercise.listing, settings.listing]);
  async function source(body: { text?: string; url?: string; name?: string; data?: string }) {
    await plans.perform(async () => { const result = await api<TrainingSource>('POST', `${PATH}/training-source`, body, { timeoutMs: 60000 }); plans.create({ title: (result.sourceName === 'Pasted text' ? 'Training plan' : result.sourceName).slice(0, 160), archived: false, sourceUrl: result.sourceUrl, sourceText: result.sourceText, sourceName: result.sourceName, schedule: '', steps: result.steps, sessions: [] }); plans.setMessage(result.note); });
  }
  return <section className="platform-panel personal-panel" aria-label="Fitness and health">
    <div className="platform-panel__heading"><div><span className="subheading">NUTRITION · MOVEMENT · TRAINING</span>{!shown && <h2>Fitness &amp; Health</h2>}</div><label>Log date<input type="date" disabled={dirty} value={day} onChange={event => setDay(event.target.value)}/></label></div>
    {!shown && <div className="personal-tabs">{(embedded ? ['Log', 'Recipes', 'Scan food', 'Edit plans', 'Targets'] : ['Training program', 'Log', 'Recipes', 'Scan food', 'Edit plans', 'Targets']).map(name => <button key={name} aria-pressed={page === name} onClick={() => setPage(name)}>{name}</button>)}</div>}
    {page === 'Training program' && <TrainingProgram askSetup={askSetup}/>}
    {page !== 'Training program' && (totals ? <><div className="personal-metrics"><Metric title="Food energy" value={`${totals.calories.toFixed(0)} kcal`}/><Metric title="Protein" value={`${totals.protein.toFixed(1)} g${totals.proteinTarget != null ? ` / ${totals.proteinTarget} g` : ''}`}/><Metric title="Carbohydrates" value={totals.carbs == null ? 'Not fully reported' : `${totals.carbs.toFixed(1)} g`}/><Metric title="Fat" value={totals.fat == null ? 'Not fully reported' : `${totals.fat.toFixed(1)} g`}/><Metric title="Fiber" value={`${totals.fiber.toFixed(1)} g${totals.fiberTarget != null ? ` / ${totals.fiberTarget} g` : ''}`}/><Metric title="Sugars" value={totals.sugars == null ? 'Not fully reported' : `${totals.sugars.toFixed(1)} g`}/><Metric title="Sodium" value={totals.sodiumMg == null ? 'Not fully reported' : `${totals.sodiumMg.toFixed(0)} mg`}/><Metric title="Cholesterol" value={totals.cholesterolMg == null ? 'Not fully reported' : `${totals.cholesterolMg.toFixed(0)} mg`}/><Metric title="Logged exercise burn" value={`${totals.burned.toFixed(0)} kcal`}/><Metric title="Intake minus exercise" value={`${(totals.calories - totals.burned).toFixed(0)} kcal`}/>{totals.baseline != null && <Metric title="Estimated energy balance" value={`${(totals.calories - totals.burned - totals.baseline).toFixed(0)} kcal`}/>}</div><small>“Not fully reported” means at least one saved food label or source omitted that nutrient. Intake minus exercise excludes resting energy and other activity. Estimated energy balance uses your optional non-exercise baseline plus logged exercise. All burn figures are estimates.</small></> : <p>Daily totals unavailable. Connect or refresh the logs to retry.</p>)}
    {page === 'Log' && <>
      <section className="nutrition-meal"><h3>Describe a meal</h3><p>Say what you ate in chat or enter it here. ZAE checks a nutrition source, asks about unclear items or serving sizes, and shows the totals for review.</p><textarea rows={3} maxLength={2000} value={mealText} onChange={event => setMealText(event.target.value)} placeholder="I ate three eggs, 4 waffles, 4 strips of bacon, 1 cup of sauteed potatoes, 1 cup of orange juice, and a protein shake for breakfast."/><div className="platform-inline"><button disabled={mealBusy || !mealText.trim()} onClick={() => void previewMeal()}>{mealBusy ? 'Checking sources…' : 'Find nutrition and review'}</button>{mealError && <small role="alert">{mealError}</small>}</div>
        {mealPreview && <MealReview preview={mealPreview} setPreview={setMealPreview} description={mealText} date={day} disabled={food.disabled || food.dirty} log={async payload => { await food.perform(async () => { await api('POST', `${PATH}/nutrition/log`, payload); setMealPreview(null); setMealText(''); }); }}/>}</section>
      <div className="personal-two"><div><h3>Food intake</h3>{food.notice}<button disabled={food.disabled || food.dirty} onClick={() => food.create({ title: '', archived: false, date: day, calories: 0, protein: 0, fiber: 0, source: 'Food label / manual entry' })}>Log food</button>{food.controls}<EntryList records={food.listing.items} disabled={food.disabled || food.dirty} open={food.open}/>
      {f && <div className="personal-editor"><fieldset disabled={food.disabled}><label>Food / serving<input maxLength={160} value={f.title} onChange={event => food.edit({ title: event.target.value })}/></label><small>Enter values for the full serving you consumed. Leave an unreported nutrient blank.</small><NumberField label="Calories (kcal)" value={f.calories} change={calories => food.edit({ calories })}/><NumberField label="Protein (g)" value={f.protein} change={protein => food.edit({ protein })}/><NumberField optional label="Carbohydrates (g)" value={f.carbs ?? null} change={carbs => food.edit({ carbs })}/><NumberField optional label="Fat (g)" value={f.fat ?? null} change={fat => food.edit({ fat })}/><NumberField optional label="Saturated fat (g)" value={f.saturatedFat ?? null} change={saturatedFat => food.edit({ saturatedFat })}/><NumberField label="Fiber (g)" value={f.fiber} change={fiber => food.edit({ fiber })}/><NumberField optional label="Sugars (g)" value={f.sugars ?? null} change={sugars => food.edit({ sugars })}/><NumberField optional label="Sodium (mg)" value={f.sodiumMg ?? null} change={sodiumMg => food.edit({ sodiumMg })}/><NumberField optional label="Cholesterol (mg)" value={f.cholesterolMg ?? null} change={cholesterolMg => food.edit({ cholesterolMg })}/><label>Nutrition source<input maxLength={300} value={f.source} onChange={event => food.edit({ source: event.target.value })}/></label>{f.sourceDetails?.length ? <details><summary>Nutrition sources ({f.sourceDetails.length})</summary>{f.sourceDetails.map((source: any, index: number) => <p key={index}>{source.name} · checked {source.checkedAt || 'date unavailable'} · {source.url && safeNutritionSource(source.url) ? <a href={safeNutritionSource(source.url)} target="_blank" rel="noreferrer">source record</a> : 'source link unavailable'}{source.nutrientsNotReported?.length ? ` · not reported: ${source.nutrientsNotReported.join(', ')}` : ''}</p>)}</details> : null}<label>Food date<input type="date" value={f.date} onChange={event => food.edit({ date: event.target.value })}/></label></fieldset>{food.actions}</div>}</div>
      <div><h3>Exercise log</h3>{exercise.notice}<button disabled={exercise.disabled || exercise.dirty} onClick={() => exercise.create({ title: '', archived: false, date: day, minutes: 30, calories: 0, source: 'Manual estimate', notes: '' })}>Log exercise</button>{exercise.controls}<EntryList records={exercise.listing.items} disabled={exercise.disabled || exercise.dirty} open={exercise.open}/>
      {e && <div className="personal-editor"><fieldset disabled={exercise.disabled}><label>Exercise<input maxLength={160} value={e.title} onChange={event => exercise.edit({ title: event.target.value })}/></label><NumberField label="Minutes" min={.1} value={e.minutes} change={minutes => exercise.edit({ minutes })}/><NumberField label="Active calories burned (estimate)" value={e.calories} change={calories => exercise.edit({ calories })}/><Select label="Burn source" value={e.source} options={['Manual estimate', 'Device estimate']} change={source => exercise.edit({ source })}/><label>Exercise date<input type="date" value={e.date} onChange={event => exercise.edit({ date: event.target.value })}/></label><label>Exercise notes<textarea maxLength={2000} value={e.notes} onChange={event => exercise.edit({ notes: event.target.value })}/></label></fieldset>{exercise.actions}</div>}</div></div>
    </>}
    {page === 'Scan food' && <section className="nutrition-meal"><h3>Read a food label or barcode</h3><p>Barcode lookups use Open Food Facts. Label photos are interpreted locally by ZAE and are never stored; check the values against the package.</p><div className="platform-inline"><button type="button" className="barcode-camera-btn" disabled={scanBusy} onClick={() => { setScanResult(null); setMealError(''); setScanning(true); }}>Scan barcode with camera</button></div>{scanning && <BarcodeScanner onClose={() => setScanning(false)} onCode={code => { setScanning(false); setBarcode(code); void scanBarcode(code); }}/>}<label>Or take a photo of the barcode<input type="file" accept="image/*" capture="environment" disabled={scanBusy} onChange={event => { void scanBarcodePhoto(event.target.files?.[0]); event.target.value = ''; }}/></label><form className="platform-inline" onSubmit={event => { event.preventDefault(); void scanBarcode(); }}><label>Barcode<input inputMode="numeric" value={barcode} onChange={event => setBarcode(event.target.value)} placeholder="Scan or type the barcode"/></label><button type="submit" disabled={scanBusy || barcode.length < 8}>Look up</button></form><label>Nutrition label photo<input type="file" accept="image/*" capture="environment" disabled={scanBusy} onChange={event => { void scanLabel(event.target.files?.[0]); event.target.value = ''; }}/></label>{scanBusy && <p>Reading the food…</p>}{mealError && <p role="alert">{mealError}</p>}{scanResult && (scanResult.found ? <article className="nutrition-item"><h4>{scanResult.title}</h4><p>{scanResult.quantity} · {scanResult.basis}</p><p>{Object.entries(scanResult.nutrients || {}).map(([key,value]) => `${key}: ${value ?? 'not listed'}`).join(' · ')}</p><a href={scanResult.source} target="_blank" rel="noreferrer">Source: {scanResult.sourceName}</a><button onClick={() => { setMealText(`1 serving ${scanResult.title}`); const match = { title: scanResult.title, nutrients: scanResult.nutrients, source: scanResult.source, sourceName: scanResult.sourceName }; setMealPreview({ items: [{ text: scanResult.title, name: scanResult.title, amount: 1, unit: 'serving', grams: null, question: 'Enter the package serving weight in grams.', nutrients: null, matches: [match], source: scanResult.source, sourceName: scanResult.sourceName }] }); setPage('Log'); }}>Use in meal review</button></article> : scanResult.values ? <div className="nutrition-review"><h4>Label text and detected facts</h4><p>{scanResult.message}</p><label>Food name<input maxLength={160} value={scanResult.productName || ''} onChange={event => setScanResult({ ...scanResult, productName: event.target.value })} placeholder="Name on the package"/></label><label>Serving size<input value={scanResult.servingSize || ''} onChange={event => setScanResult({ ...scanResult, servingSize: event.target.value })} placeholder="Confirm package serving size"/></label>{Object.entries(scanResult.values).map(([key,value]) => <NumberField key={key} label={`${key} · verify label`} value={Number(value)} change={next => setScanResult({ ...scanResult, values: { ...scanResult.values, [key]: next } })}/>) }<details><summary>Local OCR text</summary><p>{scanResult.text}</p></details><button disabled={!scanResult.productName?.trim()} onClick={() => { food.create({ title: scanResult.productName.trim(), archived: false, date: day, calories: scanResult.values.calories || 0, protein: scanResult.values.protein || 0, fiber: scanResult.values.fiber || 0, carbs: scanResult.values.carbs || 0, fat: scanResult.values.fat || 0, saturatedFat: scanResult.values.saturatedFat || 0, sugars: scanResult.values.sugars || 0, sodiumMg: scanResult.values.sodiumMg || 0, cholesterolMg: scanResult.values.cholesterolMg || 0, source: 'Local label photo · reviewed by owner' }); setPage('Log'); }}>Add verified label values to food log</button></div> : <p>{scanResult.question}</p>)}</section>}
    {page === 'Recipes' && <>{recipes.notice}<p>Keep recipes with ingredient amounts, servings, instructions, and sourced nutrition. Totals are calculated from the ingredient facts you enter or verify from a label/catalog.</p><div className="platform-inline"><button disabled={recipes.disabled || recipes.dirty} onClick={() => recipes.create({ title: '', archived: false, category: 'Meal', servings: 1, ingredients: [], instructions: '', source: 'Owner recipe' })}>New recipe</button><button disabled={recipes.disabled || recipes.dirty} onClick={() => recipes.create({ title: 'Protein pancakes', archived: false, category: 'Breakfast', servings: 1, ingredients: [], instructions: '', source: 'Owner recipe · ingredients needed' })}>Start protein pancake recipe</button></div>{recipes.controls}<EntryList records={recipes.listing.items} disabled={recipes.disabled || recipes.dirty} open={recipes.open}/>{recipes.value && <RecipeEditor recipe={recipes.value} disabled={recipes.disabled} edit={recipes.edit} actions={recipes.actions} log={async (record, nutrients) => { await food.create({ title: record.title, archived: false, date: day, calories: nutrients.calories as number, protein: nutrients.protein as number, fiber: nutrients.fiber as number, carbs: nutrients.carbs ?? undefined, fat: nutrients.fat ?? undefined, saturatedFat: nutrients.saturatedFat ?? undefined, sugars: nutrients.sugars ?? undefined, sodiumMg: nutrients.sodiumMg ?? undefined, cholesterolMg: nutrients.cholesterolMg ?? undefined, source: `Recipe · ${record.source}`, items: record.ingredients }); setPage('Log'); }}/>}</>}
    {(page === 'Edit plans' || page === 'Plans & targets') && <>{plans.notice}<div className="personal-source"><h3>Create from a source</h3><label>Printed text or video transcript<textarea rows={5} maxLength={30000} value={sourceText} onChange={event => setSourceText(event.target.value)} placeholder="Squats: 3 × 10 reps&#10;Walk: 20 minutes"/></label><button disabled={plans.disabled || plans.dirty || !sourceText.trim()} onClick={() => void source({ text: sourceText })}>Extract text into a draft</button><label>Training article / video URL<input type="url" maxLength={2000} value={sourceUrl} onChange={event => setSourceUrl(event.target.value)}/></label><button disabled={plans.disabled || plans.dirty || !sourceUrl.startsWith('https://')} onClick={() => void source({ url: sourceUrl })}>Read article / keep video reference</button><label>Import training document<input type="file" accept=".txt,.md,.pdf,.docx,.srt,.vtt" disabled={plans.disabled || plans.dirty} onChange={async event => { const file = event.target.files?.[0]; if (!file) return; await plans.perform(async () => { if (file.size > 1000000) throw new Error('Choose a training document under 1 MB.'); const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ''; bytes.forEach(byte => { binary += String.fromCharCode(byte); }); const result = await api<TrainingSource>('POST', `${PATH}/training-source`, { name: file.name, data: btoa(binary) }); plans.create({ title: file.name.slice(0, 160), archived: false, sourceUrl: result.sourceUrl, sourceText: result.sourceText, sourceName: result.sourceName, schedule: '', steps: result.steps, sessions: [] }); plans.setMessage(result.note); }); event.target.value = ''; }}/></label><small>Text PDFs and Word documents are read locally. Scans need OCR or pasted text. Video links need captions / a transcript; a link alone does not mean ZAE watched it.</small></div>
      <button disabled={plans.disabled || plans.dirty} onClick={() => plans.create({ title: '', archived: false, sourceUrl: '', sourceName: 'Owner-created plan', sourceText: '', schedule: '', steps: [], sessions: [] })}>Blank training plan</button>{plans.controls}<EntryList records={plans.listing.items} disabled={plans.disabled || plans.dirty} open={plans.open}/>
      {p && <div className="personal-editor"><fieldset disabled={plans.disabled}><label>Plan title<input maxLength={160} value={p.title} onChange={event => plans.edit({ title: event.target.value })}/></label><label>Schedule / current cycle<input maxLength={500} value={p.schedule} onChange={event => plans.edit({ schedule: event.target.value })} placeholder="e.g. Monday / Wednesday / Friday, week 1"/></label><label>Source URL<input type="url" maxLength={2000} value={p.sourceUrl} onChange={event => plans.edit({ sourceUrl: event.target.value })}/></label><details><summary>Source text · {p.sourceName}</summary><label>Source / transcript<textarea rows={8} maxLength={30000} value={p.sourceText} onChange={event => plans.edit({ sourceText: event.target.value })}/></label><button disabled={!p.sourceText.trim()} onClick={() => void plans.perform(async () => { const result = await api<TrainingSource>('POST', `${PATH}/training-source`, { text: p.sourceText }); plans.edit({ steps: result.steps }); plans.setMessage(result.note); })}>Re-extract steps from text</button></details>
      {buildPlanGroups(p.steps).map((group, groupIndex) => <section className="plan-day-card" key={`${group.label}-${group.headingIndex}`}><header><div><span className="subheading">WORKOUT DAY {groupIndex + 1}</span><h3>{group.label}</h3></div><span>{group.indices.filter(index => p.steps[index].done).length} / {group.indices.length} complete</span></header>{group.headingIndex != null && <div className="plan-day-card__meta"><label>Day name<input maxLength={300} value={p.steps[group.headingIndex].exercise} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === group.headingIndex ? { ...item, exercise: event.target.value } : item) })}/></label><label>Focus / location<input maxLength={500} value={p.steps[group.headingIndex].prescription} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === group.headingIndex ? { ...item, prescription: event.target.value } : item) })} placeholder="e.g. Chest and triceps · Gym"/></label></div>}{group.indices.map((index, position) => { const step = p.steps[index]; return <article className={`plan-exercise-card${step.done ? ' plan-exercise-card--done' : ''}`} key={index}><div className="plan-exercise-card__top"><label className="platform-check"><input type="checkbox" checked={step.done} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, done: event.target.checked } : item) })}/>Complete</label><label>Exercise<input maxLength={300} value={step.exercise} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, exercise: event.target.value } : item) })}/></label><label>Sets<input type="number" min="1" max="100" value={step.sets ?? ''} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, sets: event.target.value ? Number(event.target.value) : null } : item) })}/></label><label>Reps / range<input maxLength={80} value={step.reps ?? ''} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, reps: event.target.value } : item) })} placeholder="8–12"/></label><label>Duration<input maxLength={80} value={step.duration ?? ''} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, duration: event.target.value } : item) })} placeholder="30 sec or 20 min"/></label></div><details><summary>Exercise details</summary><div className="plan-day-card__meta"><label>Rest between sets (seconds)<input type="number" min="0" max="3600" value={step.restSeconds ?? ''} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, restSeconds: event.target.value ? Number(event.target.value) : null } : item) })}/></label><label>Equipment<input maxLength={300} value={step.equipment ?? ''} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, equipment: event.target.value } : item) })}/></label><label>Original prescription<input maxLength={500} value={step.prescription} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, prescription: event.target.value } : item) })}/></label><label>Coaching notes<textarea maxLength={1000} rows={2} value={step.notes ?? ''} onChange={event => plans.edit({ steps: p.steps.map((item, i) => i === index ? { ...item, notes: event.target.value } : item) })}/></label></div></details><footer><button disabled={position === 0} onClick={() => { const steps = [...p.steps]; [steps[index - 1], steps[index]] = [steps[index], steps[index - 1]]; plans.edit({ steps }); }}>Move up</button><button disabled={position === group.indices.length - 1} onClick={() => { const steps = [...p.steps]; [steps[index], steps[index + 1]] = [steps[index + 1], steps[index]]; plans.edit({ steps }); }}>Move down</button><button onClick={() => plans.edit({ steps: p.steps.filter((_, i) => i !== index) })}>Remove exercise</button></footer></article>})}<div className="platform-inline"><button disabled={p.steps.length >= 100} onClick={() => { const insertion = group.indices.length ? group.indices[group.indices.length - 1] + 1 : (group.headingIndex ?? p.steps.length) + 1; const steps = [...p.steps]; steps.splice(insertion, 0, { exercise: 'New exercise', prescription: '', done: false, sets: 3, reps: '8–12', duration: '', restSeconds: 90, equipment: '', notes: '' }); plans.edit({ steps }); }}>Add exercise to this day</button><button disabled={p.steps.length + group.indices.length + 1 > 100} onClick={() => { const clone = group.indices.map(index => ({ ...p.steps[index], done: false })); if (group.headingIndex != null) clone.unshift({ ...p.steps[group.headingIndex], exercise: `${p.steps[group.headingIndex].exercise} copy`, done: false }); plans.edit({ steps: [...p.steps, ...clone] }); }}>Duplicate day</button></div></section>)}
      <div className="platform-inline"><button disabled={p.steps.length >= 100} onClick={() => plans.edit({ steps: [...p.steps, { exercise: `*Day ${buildPlanGroups(p.steps).length + 1}`, prescription: 'New workout day', done: false }] })}>Add workout day</button><button disabled={p.steps.length >= 100} onClick={() => plans.edit({ steps: [...p.steps, { exercise: 'New exercise', prescription: '', done: false, sets: 3, reps: '8–12', restSeconds: 90 }] })}>Add ungrouped exercise</button><button disabled={!p.steps.length || p.sessions.length >= 200} onClick={() => plans.edit({ sessions: [...p.sessions, { date: day, steps: p.steps.map(step => ({ ...step })) }], steps: p.steps.map(step => ({ ...step, done: false })) })}>Record session / reset checklist</button><small>{p.steps.filter(step => step.done).length} / {p.steps.length} complete. Session history records the checked exercises.</small></div><details><summary>Session history ({p.sessions.length})</summary>{p.sessions.map((session, index) => <p key={index}>{session.date}: {session.steps.filter(step => step.done).length} / {session.steps.length} steps complete — {session.steps.filter(step => step.done).map(step => step.exercise).join(', ') || 'No completed steps'}</p>)}</details></fieldset>{plans.actions}</div>}
    </>}
    {(page === 'Targets' || page === 'Plans & targets') && <>{settings.notice}<p>Set your own nutrition targets. Optional baseline is your daily energy expenditure excluding exercise entered here. Do not enter a wearable's total expenditure and then add that same exercise again.</p>{settings.controls}<EntryList records={settings.listing.items} disabled={settings.disabled || settings.dirty} open={settings.open}/><button disabled={settings.disabled || settings.dirty || settings.listing.total > 0} onClick={() => settings.create({ title: 'My targets', archived: false, proteinTarget: null, fiberTarget: null, baselineCalories: null })}>Set targets</button>{s && <div className="personal-editor"><fieldset disabled={settings.disabled}><NumberField optional label="Protein target (g)" value={s.proteinTarget} change={proteinTarget => settings.edit({ proteinTarget })}/><NumberField optional label="Fiber target (g)" value={s.fiberTarget} change={fiberTarget => settings.edit({ fiberTarget })}/><NumberField optional label="Non-exercise baseline (kcal/day)" value={s.baselineCalories} change={baselineCalories => settings.edit({ baselineCalories })}/></fieldset>{settings.actions}</div>}</>}
  </section>;
}

function buildPlanGroups(steps: Step[]) {
  const groups: { label: string; headingIndex: number | null; indices: number[] }[] = [];
  let current: { label: string; headingIndex: number | null; indices: number[] } | null = null;
  steps.forEach((step, index) => {
    if (/^\s*\*?\s*(?:day\s*\d+|monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b/i.test(step.exercise)) {
      current = { label: step.exercise.replace(/^\s*\*\s*/, ''), headingIndex: index, indices: [] }; groups.push(current);
    } else {
      if (!current) { current = { label: 'Workout', headingIndex: null, indices: [] }; groups.push(current); }
      current.indices.push(index);
    }
  });
  return groups;
}

function MealReview({ preview, setPreview, description, date, disabled, log }: { preview: any; setPreview: (value: any) => void; description: string; date: string; disabled: boolean; log: (value: any) => Promise<void> }) {
  const [searching, setSearching] = useState<number | null>(null); const [error, setError] = useState('');
  function patch(index: number, changes: any) { setPreview((old: any) => ({ ...old, items: old.items.map((item: any, i: number) => i === index ? { ...item, ...changes } : item) })); }
  async function search(index: number, query: string) { setSearching(index); setError(''); try { const result = await api<any>('POST', `${PATH}/nutrition/suggest`, { query }, { timeoutMs: 30_000 }); patch(index, { matches: result.matches || [], selected: null, nutrients: null, question: result.matches?.length ? 'Choose the closest item, then confirm the amount you consumed.' : `No USDA records found for ${query}. Try the exact product name or use a package-label photo.` }); } catch (failure) { setError(errorText(failure)); } finally { setSearching(null); } }
  function choose(index: number, match: any) { const item = preview.items[index]; const nutrients = item.grams > 0 ? Object.fromEntries(Object.entries(match.nutrients).map(([key, amount]: any) => [key, amount == null ? null : Number(amount) * Number(item.grams) / 100])) : null; const missingCore = nutrients && ['calories','protein','fiber'].some(key => nutrients[key] == null); patch(index, { selected: match, source: match.source, sourceName: match.sourceName, nutrients, question: item.grams > 0 ? (missingCore ? 'This record is missing calories, protein, or fiber. Use a label photo before logging.' : '') : 'Enter the grams for the portion you ate.' }); }
  const complete = preview.items.length > 0 && preview.items.every((item: any) => item.nutrients && ['calories','protein','fiber'].every(key => item.nutrients[key] != null));
  const needsAnswers = preview.items.some((item: any) => Boolean(item.question));
  const total: Record<string, number | null> = {};
  for (const key of ['calories','protein','carbs','fat','saturatedFat','fiber','sugars','sodiumMg','cholesterolMg']) total[key] = preview.items.every((item: any) => item.nutrients?.[key] != null) ? preview.items.reduce((sum: number, item: any) => sum + Number(item.nutrients[key]), 0) : null;
  return <div className={needsAnswers ? 'nutrition-modal-backdrop' : 'nutrition-modal-backdrop nutrition-modal-backdrop--inline'}><div className="nutrition-review" role={needsAnswers ? 'dialog' : undefined} aria-modal={needsAnswers || undefined} aria-label="Review meal nutrition"><header className="nutrition-review__header"><div><h4>Meal review · {preview.items.length} items</h4><p>{preview.message}</p></div>{needsAnswers && <button onClick={() => setPreview(null)}>Close</button>}</header>{preview.items.map((item: any, index: number) => { const selected = item.selected || item.matches?.[0]; return <article className="nutrition-item" key={index}><strong>{item.text}</strong>{item.question && <p className="nutrition-question">{item.question}</p>}{item.note && <small className="nutrition-note">Portion: {item.note}</small>}<div className="nutrition-recipe__settings"><label>Food / brand detail<input maxLength={120} value={item.query ?? item.name} onChange={event => patch(index, { query: event.target.value })}/></label><button disabled={searching === index || !(item.query ?? item.name)?.trim()} onClick={() => void search(index, item.query ?? item.name)}>{searching === index ? 'Searching…' : 'Search nutrition sources'}</button></div>{item.matches?.length > 0 && <><label>Food match<select value={String(selected?.fdcId ?? selected?.source)} onChange={event => { const match = item.matches.find((candidate: any) => String(candidate.fdcId ?? candidate.source) === event.target.value); if (match) choose(index, match); }}>{item.matches.map((match: any) => <option key={match.fdcId ?? match.source} value={match.fdcId ?? match.source}>{match.title} · {match.sourceName}</option>)}</select></label><label>Portion weight (g)<input type="number" min="0" step="any" value={item.grams ?? ''} onChange={event => { const grams = Number(event.target.value); const nutrients = grams > 0 && selected ? Object.fromEntries(Object.entries(selected.nutrients).map(([key, amount]: any) => [key, amount == null ? null : Number(amount) * grams / 100])) : null; const missingCore = nutrients && ['calories','protein','fiber'].some(key => nutrients[key] == null); patch(index, { grams, nutrients, question: grams > 0 ? (missingCore ? 'This record is missing calories, protein, or fiber. Use a label photo before logging.' : '') : 'Enter the grams for the portion you ate.' }); }}/></label><small>{selected.sourceName} · checked {selected.checkedAt || 'this session'} · <a href={selected.source} target="_blank" rel="noreferrer">view source</a></small></>}{item.nutrients && <small>{Object.entries(item.nutrients).filter(([key]) => ['calories','protein','carbs','fat','fiber','sugars','sodiumMg','cholesterolMg'].includes(key)).map(([key,value]) => `${key === 'calories' ? 'kcal' : key === 'sodiumMg' ? 'sodium mg' : key === 'cholesterolMg' ? 'cholesterol mg' : key} ${value == null ? 'not available' : Number(value).toFixed(1)}`).join(' · ')}</small>}</article>; })}{error && <p role="alert">{error}</p>}{complete && <><h4>Meal totals</h4><p>{Object.entries(total).map(([key,value]) => `${key}: ${value == null ? 'not fully reported' : Number(value).toFixed(1)}`).join(' · ')}</p><button disabled={disabled} onClick={() => void log({ description, date, items: preview.items.map((item: any) => ({ ...item, source: (item.selected || item.matches[0]).source, sourceName: (item.selected || item.matches[0]).sourceName }))})}>Log reviewed meal</button></>}</div></div>;
}

function RecipeEditor({ recipe, disabled, edit, actions, log }: { recipe: Recipe; disabled: boolean; edit: (value: Partial<Recipe>) => void; actions: ReactNode; log: (value: Recipe, nutrients: Record<string, number | null>) => Promise<void> }) {
  const [error, setError] = useState(''); const [math, setMath] = useState<any>(null); const ingredients = recipe.ingredients || [];
  const canLog = ingredients.length > 0 && ingredients.every((item: any) => item.name?.trim() && item.source?.trim() && ['calories','protein','fiber'].every(key => item.nutrients?.[key] != null));
  const add = () => edit({ ingredients: [...ingredients, { name: '', amount: '', unit: 'g', nutrients: emptyNutrients(), source: '' }] });
  async function calculate() { setError(''); try { const result = await api<any>('POST', `${PATH}/nutrition/recipe-math`, { ingredients, servings: recipe.servings }); setMath(result); } catch (failure) { setError(errorText(failure)); } }
  async function logServing() { setError(''); try { const result = await api<any>('POST', `${PATH}/nutrition/recipe-math`, { ingredients, servings: recipe.servings }); setMath(result); if (['calories','protein','fiber'].some(key => result.perServing[key] == null)) { setError('Add the missing calories, protein, or fiber for every ingredient before logging.'); return; } await log(recipe, result.perServing); } catch (failure) { setError(errorText(failure)); } }
  return <div className="personal-editor nutrition-recipe"><fieldset disabled={disabled}><label>Recipe name<input maxLength={160} value={recipe.title} onChange={event => edit({ title: event.target.value })}/></label><div className="nutrition-recipe__settings"><label>Category<input maxLength={60} value={recipe.category} onChange={event => edit({ category: event.target.value })}/></label><NumberField label="Servings" min={.1} value={recipe.servings} change={servings => edit({ servings })}/><label>Nutrition source<input maxLength={300} value={recipe.source} onChange={event => edit({ source: event.target.value })}/></label></div><h4>Ingredients and nutrition</h4>{ingredients.map((item: any, index: number) => <IngredientRow key={index} item={item} onChange={next => edit({ ingredients: ingredients.map((old: any, i: number) => i === index ? next : old) })} onRemove={() => edit({ ingredients: ingredients.filter((_: any, i: number) => i !== index) })}/>)}<RecipeTotals ingredients={ingredients as any} servings={recipe.servings}/>{ingredients.length > 0 && <div className="platform-inline"><button type="button" disabled={!canLog} onClick={() => void logServing()}>Log one serving</button>{!canLog && <small>To log, every ingredient needs calories, protein and fiber, and a source (picking a search match fills it).</small>}</div>}<button type="button" disabled={ingredients.length >= 100} onClick={add}>Add ingredient</button><label>Instructions<textarea rows={4} maxLength={10000} value={recipe.instructions} onChange={event => edit({ instructions: event.target.value })}/></label><button type="button" disabled={!ingredients.length} onClick={() => void calculate()}>Calculate nutrition per recipe and serving</button>{error && <p role="alert">{error}</p>}{math && <div className="nutrition-review"><strong>Per recipe</strong><p>{Object.entries(math.perRecipe).map(([key,value]) => `${key}: ${value == null ? 'not reported' : Number(value).toFixed(1)}`).join(' · ')}</p><strong>Per serving</strong><p>{Object.entries(math.perServing).map(([key,value]) => `${key}: ${value == null ? 'not reported' : Number(value).toFixed(1)}`).join(' · ')}</p><button type="button" disabled={!canLog} onClick={() => void logServing()}>Log one serving</button></div>}</fieldset>{actions}</div>;
}

function Select({ label, value, options, change }: { label: string; value: string; options: string[]; change: (value: string) => void }) { return <label>{label}<select value={value} onChange={e => change(e.target.value)}>{options.map(option => <option key={option}>{option}</option>)}</select></label>; }
function safeNutritionSource(value: string): string | undefined { try { const url = new URL(value); return url.protocol === 'https:' && !url.username && !url.password ? url.href : undefined; } catch { return undefined; } }
function NumberField({ label, value, change, optional = false, min = 0 }: { label: string; value: number | null; change: (value: number) => void; optional?: boolean; min?: number }) {
  return <label>{label}<input type="number" min={min} step="any" value={value ?? ''} onChange={e => change((optional && e.target.value === '' ? null : Number(e.target.value)) as number)}/></label>;
}
function EntryList({ records, disabled, open }: { records: Summary[]; disabled: boolean; open: (id: string) => void }) { return <div className="personal-entries">{records.map(row => <button key={row.id} disabled={disabled} onClick={() => open(row.id!)}><strong>{row.title}</strong><small>{row.date}{row.calories != null ? ` · ${row.calories} kcal` : ''}{row.protein != null ? ` · ${row.protein} g protein · ${row.fiber} g fiber` : ''}{row.carbs != null ? ` · ${row.carbs} g carbs` : ''}{row.fat != null ? ` · ${row.fat} g fat` : ''}{row.source ? ` · ${row.source}` : ''}</small></button>)}</div>; }
function Metric({ title, value }: { title: string; value: ReactNode }) { return <div><small>{title}</small><strong>{value}</strong></div>; }
